294	    /**
295	     * SkipListener: 예외 발생 시 로그
296	     */
297	    @Bean
298	    public SkipListener<OrderShipment, OrderShipment> shipmentSkipListener() {
299	        return new SkipListener<>() {
300	            @Override
301	            public void onSkipInProcess(OrderShipment item, Throwable t) {
302	                if (item != null) {
303	                    log.error("[Skip] 배송 상태 처리 스킵: shipmentId={}, trackingNumber={}, status={}, 사유={}",
304	                            item.getId(),
305	                            item.getTrackingNumber(),
306	                            item.getStatus(),
307	                            t.getMessage(),
308	                            t);
309	                } else {
310	                    log.error("[Skip] 배송 상태 처리 스킵: item=null, 사유={}", t.getMessage(), t);
311	                }
312	            }
313	
314	            @Override
315	            public void onSkipInRead(Throwable t) {
316	                log.error("[SkipRead] 배송 정보 읽기 스킵: 사유={}", t.getMessage(), t);
317	            }
318	
319	            @Override
320	            public void onSkipInWrite(OrderShipment item, Throwable t) {
321	                if (item != null) {
322	                    log.error("[SkipWrite] 배송 상태 저장 스킵: shipmentId={}, trackingNumber={}, status={}, 사유={}",
323	                            item.getId(),
324	                            item.getTrackingNumber(),
325	                            item.getStatus(),
326	                            t.getMessage(),
327	                            t);
328	                } else {
329	                    log.error("[SkipWrite] 배송 상태 저장 스킵: item=null, 사유={}", t.getMessage(), t);
330	                }
331	            }
332	        };
333	    }
