236	     * @param trackingNumber 운송장 번호
237	     */
238	    @Transactional
239	    public void updateTrackingInfo(Long shipmentId, String courier, String trackingNumber) {
240	        log.info("배송 운송장 정보 업데이트: shipmentId={}, courier={}, trackingNumber={}",
241	                shipmentId, courier, trackingNumber);
242	
243	        if (courier == null || courier.isBlank() || trackingNumber == null || trackingNumber.isBlank()) {
244	            log.warn("유효하지 않은 배송사 또는 운송장 번호: shipmentId={}", shipmentId);
245	            throw new ShipmentException(ShipmentErrorCode.TRACKING_INFO_REQUIRED);
246	        }
247	
248	        try {
249	            OrderShipment shipment = orderShipmentRepository.findById(shipmentId)
250	                    .orElseThrow(() -> new ShipmentException(
251	                            ShipmentErrorCode.SHIPMENT_NOT_FOUND,
